window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[96]={"id":"096","numero":96,"titre":"Neuropathies périphériques","objectifs":[{"id":"96-1","rang":"A","rubrique":"Définition","titre":"Connaître la classification et la définition des différents types de neuropathies périphériques","contenu":"<p>La <span class=\"kw-def\"><strong>neuropathie périphérique</strong></span> désigne toute atteinte du système nerveux périphérique, c'est-à-dire en aval du corps cellulaire du neurone — à distinguer d'une atteinte du système nerveux central. La <span class=\"kw-def\">classification</span> combine <strong>deux axes</strong> : la topographie de l'atteinte et son mécanisme physiopathologique.</p>\n      <p><strong>Axe 1 — <span class=\"kw-def\">Classification</span> topographique</strong></p>\n      <table >\n        <thead><tr><th>Niveau</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Corne antérieure</strong></td>\n            <td><strong>Tableau :</strong> <span class=\"kw-clinique\">déficit moteur pur</span> dans un territoire médullaire ; <span class=\"kw-clinique\">amyotrophie</span> ; <span class=\"kw-clinique\">crampes et fasciculations</span><br><strong>Étiologies :</strong> <span class=\"kw-etio\">SLA</span> ; <span class=\"kw-etio\">poliomyélite antérieure aiguë</span> ; <span class=\"kw-etio\">amyotrophie spinale progressive</span></td>\n          </tr>\n          <tr>\n            <td><strong>Racine</strong> (radiculopathie)</td>\n            <td><span class=\"kw-clinique\">déficit moteur et sensitif</span> dans le territoire de la racine ; <span class=\"kw-clinique\">trajet douloureux</span> spécifique ; <span class=\"kw-clinique\">abolition du ROT</span> correspondant (sauf L5 — pas de réflexe L5)</td>\n          </tr>\n          <tr>\n            <td><strong>Queue de cheval</strong></td>\n            <td>atteinte pluriradiculaire sous L2 : <span class=\"kw-clinique\">déficit moteur</span> et sensitif des MI ; <span class=\"kw-alerte\">anesthésie en selle</span> ; <span class=\"kw-alerte\">troubles sphinctériens</span></td>\n          </tr>\n          <tr>\n            <td><strong>Plexus</strong> (plexopathie)</td>\n            <td>atteinte tronculaire multiple, confluente, dans le territoire d'un plexus</td>\n          </tr>\n          <tr>\n            <td><strong>Tronc nerveux</strong></td>\n            <td><span class=\"kw-clinique\">mononeuropathie</span> (un tronc) ou <span class=\"kw-clinique\">mononeuropathie multiple</span> (plusieurs troncs) — déficit systématisé au territoire nerveux</td>\n          </tr>\n          <tr>\n            <td><strong>Neuropathies diffuses</strong></td>\n            <td><span class=\"kw-clinique\">polyneuropathie</span> ; <span class=\"kw-clinique\">polyradiculonévrite</span> ; <span class=\"kw-clinique\">neuronopathie</span> — atteinte étendue, non focale (voir obj-2)</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Axe 2 — Mécanisme physiopathologique (arbitré par l'ENMG)</strong></p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Substratum</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Axonal</strong></span></td>\n            <td><span class=\"kw-alerte\">dégénérescence axonale</span> ; signes de <span class=\"kw-clinique\">dénervation</span> à l'<span class=\"kw-imagerie\">EMG</span> de détection (potentiels de <span class=\"kw-clinique\">fibrillation</span>, potentiels lents de dénervation)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Démyélinisant</strong></span></td>\n            <td>perte de myéline ; <span class=\"kw-clinique\">ralentissement de la vitesse de conduction</span> ; <span class=\"kw-clinique\">blocs de conduction</span> possibles</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Neuronopathie</strong></span></td>\n            <td>atteinte du corps cellulaire : <span class=\"kw-def\">ganglion rachidien</span> (sensitif) ou corne antérieure (moteur)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> La <span class=\"kw-def\">classification</span> combine 2 axes : topographie (où ?) + mécanisme (axonal <span class=\"kw-bio\">vs</span> démyélinisant <span class=\"kw-bio\">vs</span> neuronopathie). L'ENMG arbitre le mécanisme.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 247 — <span class=\"kw-etio\">Diabète</span> · 95 — Radiculalgie - Syndrome canalaire · 97 — Polyradiculonévrite aigue <span class=\"kw-etio\">inflammatoire</span></em></p>","frequence":1},{"id":"96-2","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une neuropathie périphérique (examen clinique, démarche diagnostique)","contenu":"<p>Le diagnostic d'une neuropathie périphérique suit une démarche en <strong>3 étapes</strong> : (1) reconnaître le <span class=\"kw-def\">syndrome neurogène périphérique</span> ; (2) en préciser la topographie ; (3) en déterminer le mécanisme grâce à l'ENMG.</p>\n      <p><strong>Étape 1 — Reconnaître le syndrome neurogène périphérique</strong></p>\n      <table >\n        <thead><tr><th>Signe</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\"><strong>Déficit moteur périphérique</strong></span></td><td>faiblesse, fatigabilité anormale à l'effort</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Amyotrophie</strong></span></td><td>apparaît après quelques semaines d'<span class=\"kw-clinique\">évolution</span></td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Crampes, fasciculations</strong></span></td><td>témoignant de l'atteinte du motoneurone inférieur</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Troubles sensitifs</strong></span></td><td><span class=\"kw-clinique\">paresthésies</span>, dysesthésies, hypoesthésie</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Aréflexie / hyporéflexie</strong></span></td><td>abolition ou diminution des réflexes ostéo-tendineux</td></tr>\n          <tr><td><span class=\"kw-def\"><strong>Absence de signe pyramidal</strong></span></td><td>pas de Babinski, pas de spasticité — discrimine de la SLA (obj-4)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Outils du diagnostic</strong></p>\n      <ul>\n        <li><strong>Interrogatoire :</strong> <span class=\"kw-etio\">antécédents familiaux</span> ; <span class=\"kw-etio\">médicaments neurotoxiques</span> ; <span class=\"kw-etio\">diabète</span> ; <span class=\"kw-etio\">alcool</span> ; <span class=\"kw-etio\">exposition professionnelle</span></li>\n        <li><strong>Examen clinique systématisé :</strong> sensibilité <span class=\"kw-clinique\">tactile</span>, <span class=\"kw-clinique\">thermoalgique</span>, <span class=\"kw-clinique\">proprioceptive</span> et <span class=\"kw-clinique\">vibratoire</span> ; <span class=\"kw-clinique\">ROT</span> ; testing de la <span class=\"kw-clinique\">force musculaire</span></li>\n        <li><strong>Composante douloureuse :</strong> questionnaire <span class=\"kw-clinique\"><strong>DN4</strong></span> pour caractériser une douleur neuropathique</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Une polyneuropathie axonale longueur-dépendante peut être longtemps <span class=\"kw-clinique\">paucisymptomatique</span> chez un diabétique âgé. <span class=\"kw-alerte\">L'examen des pieds (monofilament 10 g) est obligatoire à chaque consultation.</span></div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 134 — Bases neurophysiologiques de la douleur · 95 — Radiculalgie - Syndrome canalaire</em></p>","frequence":0},{"id":"96-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une polyneuropathie, d’une mononeuropathie, d’une mononeuropathie multiple, d’une polyradiculoneuropathie (examen clinique, démarche diagnostique)","contenu":"<p>Quatre grands cadres sémiologiques structurent le diagnostic topographique d'une neuropathie diffuse. Chacun a une <strong>signature discriminante</strong>.</p>\n      <table >\n        <thead><tr><th>Cadre</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Polyneuropathie (PNP)</strong></span></td>\n            <td><strong>Topographie :</strong> <span class=\"kw-clinique\">longueur-dépendante</span>, <span class=\"kw-clinique\">symétrique</span>, <span class=\"kw-clinique\">distale</span>, synchrone (« <span class=\"kw-clinique\">gants &amp; chaussettes</span> »)<br><strong>Installation :</strong> subaiguë ou chronique<br><strong>Atteinte :</strong> <span class=\"kw-clinique\">sensitive ≫ motrice</span> ; <span class=\"kw-clinique\">ROT abolis distalement</span><br><strong>Négatif :</strong> <span class=\"kw-ci\">pas d'atteinte respiratoire</span>, <span class=\"kw-ci\">pas de nerf crânien</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Mononeuropathie (MN)</strong></span></td>\n            <td><strong>Topographie :</strong> un <span class=\"kw-clinique\">tronc nerveux unique</span>, <span class=\"kw-clinique\">focale</span><br><strong>Installation :</strong> aiguë (<span class=\"kw-etio\">compression</span>, <span class=\"kw-etio\">traumatisme</span>)<br><strong>Atteinte :</strong> <span class=\"kw-clinique\">sensitive + motrice</span> systématisée au territoire du nerf</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Mononeuropathie multiple</strong></span> (multinévrite)</td>\n            <td><strong>Topographie :</strong> <span class=\"kw-clinique\">tronculaire multiple</span>, <span class=\"kw-clinique\">asymétrique</span> et <span class=\"kw-clinique\">asynchrone</span><br><strong>Installation :</strong> aiguë ou subaiguë<br><strong>Particularité :</strong> <span class=\"kw-alerte\">urgence diagnostique</span> — évoquer une <span class=\"kw-etio\">vascularite</span> (obj-9, obj-10)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Polyradiculonévrite (PRN)</strong></span></td>\n            <td><strong>Topographie :</strong> <span class=\"kw-clinique\">racines + troncs + nerfs crâniens</span>, <span class=\"kw-clinique\">bilatérale</span>, <span class=\"kw-clinique\">symétrique</span>, <span class=\"kw-clinique\">proximale ET distale</span><br><strong>Installation :</strong> aiguë (jours) ou chronique<br><strong>Atteinte :</strong> <span class=\"kw-clinique\">sensitive ET motrice</span> ; <span class=\"kw-clinique\">aréflexie diffuse</span><br><strong>Paraclinique :</strong> <span class=\"kw-bio\">hyperprotéinorachie du LCS</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewBox=\"-16 0 592 360\" role=\"img\" aria-label=\"Schéma des quatre patterns de distribution spatiale des neuropathies diffuses sur une silhouette corporelle. La polyneuropathie est longueur-dépendante, symétrique et distale, touchant les deux pieds puis les deux mains, en gants et chaussettes. La mononeuropathie atteint un tronc nerveux unique, de façon focale et asymétrique, par exemple un seul membre. La mononeuropathie multiple est tronculaire multiple, asymétrique et asynchrone, touchant plusieurs territoires nerveux dispersés. La polyradiculonévrite est bilatérale, symétrique, proximale et distale, touchant racines, troncs et nerfs crâniens.\" style=\"height:auto;display:block;border-radius:8px\">\n          <text class=\"tx-title\" x=\"280\" y=\"18\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"700\">Patterns de distribution sur silhouette</text>\n          <text class=\"tx-muted\" x=\"280\" y=\"34\" text-anchor=\"middle\" font-size=\"10.5\">zones colorées = territoires atteints</text>\n\n          <!-- ===== Panneau 1 : PNP ===== -->\n          <text class=\"tx-purple\" x=\"80\" y=\"58\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"700\">PNP</text>\n          <text class=\"tx-muted\" x=\"80\" y=\"72\" text-anchor=\"middle\" font-size=\"9\">longueur-dép. · symétrique · distale</text>\n          <line class=\"ln\" x1=\"80\" y1=\"92\" x2=\"80\" y2=\"156\" stroke-width=\"9\" stroke-linecap=\"round\"/>\n          <circle class=\"fb-grey\" cx=\"80\" cy=\"86\" r=\"9\"/>\n          <line class=\"ln\" x1=\"80\" y1=\"104\" x2=\"58\" y2=\"132\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n          <line class=\"ln\" x1=\"80\" y1=\"104\" x2=\"102\" y2=\"132\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n          <line class=\"ln\" x1=\"80\" y1=\"156\" x2=\"66\" y2=\"206\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n          <line class=\"ln\" x1=\"80\" y1=\"156\" x2=\"94\" y2=\"206\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n          <circle class=\"fb-red\" cx=\"66\" cy=\"206\" r=\"7\"/>\n          <circle class=\"fb-red\" cx=\"94\" cy=\"206\" r=\"7\"/>\n          <circle class=\"fb-red\" cx=\"58\" cy=\"132\" r=\"6\"/>\n          <circle class=\"fb-red\" cx=\"102\" cy=\"132\" r=\"6\"/>\n          <text class=\"tx-red\" x=\"80\" y=\"232\" text-anchor=\"middle\" font-size=\"9\">gants &amp; chaussettes</text>\n\n          <!-- ===== Panneau 2 : MN ===== -->\n          <text class=\"tx-purple\" x=\"200\" y=\"58\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"700\">MN</text>\n          <text class=\"tx-muted\" x=\"200\" y=\"72\" text-anchor=\"middle\" font-size=\"9\">un tronc · focale</text>\n          <line class=\"ln\" x1=\"200\" y1=\"92\" x2=\"200\" y2=\"156\" stroke-width=\"9\" stroke-linecap=\"round\"/>\n          <circle class=\"fb-grey\" cx=\"200\" cy=\"86\" r=\"9\"/>\n          <line class=\"ln\" x1=\"200\" y1=\"104\" x2=\"178\" y2=\"132\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n          <line class=\"fb-red\" x1=\"200\" y1=\"104\" x2=\"222\" y2=\"132\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n          <line class=\"ln\" x1=\"200\" y1=\"156\" x2=\"186\" y2=\"206\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n          <line class=\"ln\" x1=\"200\" y1=\"156\" x2=\"214\" y2=\"206\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n          <text class=\"tx-red\" x=\"200\" y=\"232\" text-anchor=\"middle\" font-size=\"9\">1 territoire nerveux</text>\n\n          <!-- ===== Panneau 3 : MNM ===== -->\n          <text class=\"tx-purple\" x=\"360\" y=\"58\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"700\">MNM</text>\n          <text class=\"tx-muted\" x=\"360\" y=\"72\" text-anchor=\"middle\" font-size=\"9\">asymétrique · asynchrone</text>\n          <line class=\"ln\" x1=\"360\" y1=\"92\" x2=\"360\" y2=\"156\" stroke-width=\"9\" stroke-linecap=\"round\"/>\n          <circle class=\"fb-grey\" cx=\"360\" cy=\"86\" r=\"9\"/>\n          <line class=\"fb-red\" x1=\"360\" y1=\"104\" x2=\"338\" y2=\"132\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n          <line class=\"ln\" x1=\"360\" y1=\"104\" x2=\"382\" y2=\"132\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n          <line class=\"ln\" x1=\"360\" y1=\"156\" x2=\"346\" y2=\"206\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n          <line class=\"fb-red\" x1=\"360\" y1=\"156\" x2=\"374\" y2=\"206\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n          <text class=\"tx-red\" x=\"360\" y=\"232\" text-anchor=\"middle\" font-size=\"9\">troncs dispersés</text>\n\n          <!-- ===== Panneau 4 : PRN ===== -->\n          <text class=\"tx-purple\" x=\"480\" y=\"58\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"700\">PRN</text>\n          <text class=\"tx-muted\" x=\"480\" y=\"72\" text-anchor=\"middle\" font-size=\"9\">proximale ET distale · bilatérale</text>\n          <line class=\"fb-red\" x1=\"480\" y1=\"92\" x2=\"480\" y2=\"156\" stroke-width=\"9\" stroke-linecap=\"round\"/>\n          <circle class=\"fb-red\" cx=\"480\" cy=\"86\" r=\"9\"/>\n          <line class=\"fb-red\" x1=\"480\" y1=\"104\" x2=\"458\" y2=\"132\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n          <line class=\"fb-red\" x1=\"480\" y1=\"104\" x2=\"502\" y2=\"132\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n          <line class=\"fb-red\" x1=\"480\" y1=\"156\" x2=\"466\" y2=\"206\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n          <line class=\"fb-red\" x1=\"480\" y1=\"156\" x2=\"494\" y2=\"206\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n          <text class=\"tx-red\" x=\"480\" y=\"232\" text-anchor=\"middle\" font-size=\"9\">racines + troncs + n. crâniens</text>\n\n          <!-- ===== Bandeau de synthèse ===== -->\n          <rect class=\"fb-grey\" x=\"24\" y=\"252\" width=\"512\" height=\"92\" rx=\"8\"/>\n          <text class=\"tx-grey\" x=\"40\" y=\"274\" font-size=\"10.5\"><tspan font-weight=\"700\">PNP</tspan> — symétrique, distale, sensitive supérieure à motrice ; ROT abolis distalement</text>\n          <text class=\"tx-grey\" x=\"40\" y=\"292\" font-size=\"10.5\"><tspan font-weight=\"700\">MN</tspan> — focale, aiguë (compression, traumatisme) ; sensitivomotrice systématisée</text>\n          <text class=\"tx-grey\" x=\"40\" y=\"310\" font-size=\"10.5\"><tspan font-weight=\"700\">MNM</tspan> — asymétrique + asynchrone ; <span class=\"kw-alerte\">urgence</span> : évoquer une vascularite</text>\n          <text class=\"tx-grey\" x=\"40\" y=\"328\" font-size=\"10.5\"><tspan font-weight=\"700\">PRN</tspan> — sensitive ET motrice, aréflexie diffuse ; hyperprotéinorachie du <span class=\"kw-bio\">LCS</span></text>\n        </svg>\n        <figcaption>Topographie comparée des 4 cadres sémiologiques : la PNP atteint les extrémités symétriquement (gants &amp; chaussettes), la MN un seul tronc, la MNM plusieurs troncs de façon asymétrique et asynchrone, la PRN l'ensemble racines-troncs-nerfs crâniens. Source : fiche source EDN item 96 — Neuropathies diffuses, obj-2.</figcaption>\n      </figure>\n      <p>Un 5<sup>e</sup> cadre, la <span class=\"kw-def\">neuronopathie sensitive</span> (ganglionopathie) — atteinte purement sensitive non longueur-dépendante — est détaillé en obj-3.</p>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Le 1<sup>er</sup> réflexe devant tout déficit neuro distal est de répondre à 4 questions : symétrique ou asymétrique ? proximale ou distale ? racines ou troncs ? sensitive, motrice ou les deux ? Cela oriente vers PNP, MN, MNM ou PRN avant même l'ENMG.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 97 — Polyradiculonévrite aigue <span class=\"kw-etio\">inflammatoire</span> · 95 — Radiculalgie - Syndrome canalaire</em></p>","frequence":2},{"id":"96-4","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une neuronopathie sensitive (examen clinique, démarche diagnostique)","contenu":"<p>La <span class=\"kw-def\"><strong>neuronopathie sensitive</strong></span> (ou <span class=\"kw-def\">ganglionopathie</span>) est une dégénérescence diffuse des <span class=\"kw-def\">corps cellulaires des fibres sensitives</span>, situés dans le <span class=\"kw-def\">ganglion de la racine dorsale</span> (ganglions rachidiens).</p>\n      <table >\n        <thead><tr><th>Particularité</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\"><strong>Atteinte exclusivement sensitive</strong></span></td><td>discrimine de la PNP et de la MNM, qui comportent une atteinte motrice</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Non longueur-dépendante</strong></span></td><td><span class=\"kw-clinique\">déficit sensitif</span> parfois très étendu, parfois très <span class=\"kw-clinique\">multifocal</span></td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Atteinte d'emblée MI + MS</strong></span></td><td>≠ PNP qui débute aux pieds ; face et/ou tronc touchés dans <span class=\"kw-chiffre\">25 %</span> des cas</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Aréflexie diffuse</strong></span></td><td>quasi-constante ; <span class=\"kw-clinique\">ataxie</span> fréquente</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Paraclinique</strong></p>\n      <ul>\n        <li><strong>ENMG :</strong> <span class=\"kw-clinique\">abolition diffuse des potentiels sensitifs</span> aux 4 membres, <span class=\"kw-clinique\">sans anomalie des potentiels moteurs</span> — signature de la ganglionopathie</li>\n        <li><strong><span class=\"kw-bio\">LCS</span> :</strong> <span class=\"kw-bio\">hyperprotéinorachie modérée (&lt; 1 g/L)</span> ; une <span class=\"kw-bio\">réaction cellulaire</span> évoque une origine <span class=\"kw-etio\">paranéoplasique</span></li>\n        <li><strong>Immunologie :</strong> <span class=\"kw-bio\">AC anti-Hu</span> = signature <span class=\"kw-etio\">paranéoplasique</span> (<span class=\"kw-etio\">cancer du poumon à petites cellules</span>)</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Discriminant clé.</strong> Une atteinte <span class=\"kw-clinique\">sensitive pure</span>, <span class=\"kw-clinique\">non longueur-dépendante</span>, touchant d'emblée les membres supérieurs = penser ganglionopathie. <span class=\"kw-alerte\">Éliminer un cancer du poumon à petites cellules</span> (<span class=\"kw-imagerie\">TDM</span> thoracique, AC anti-Hu).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 309 — Tumeurs du poumon · 193 — <span class=\"kw-etio\">Vascularite</span> systémique</em></p>","frequence":0},{"id":"96-5","rang":"A","rubrique":"Diagnostic positif","titre":"Distinguer cliniquement une neuropathie périphérique et sclérose latérale amyotrophique","contenu":"<p>Le <span class=\"kw-def\">diagnostic différentiel</span> entre une <span class=\"kw-def\">neuropathie périphérique</span> et une <span class=\"kw-etio\">sclérose latérale amyotrophique (SLA)</span> repose sur l'examen clinique : la <span class=\"kw-etio\">SLA</span> associe une atteinte du <span class=\"kw-def\">motoneurone supérieur</span> ET du <span class=\"kw-def\">motoneurone inférieur</span>.</p>\n      <table >\n        <thead><tr><th>Critère</th><th>Neuropathie périphérique</th><th>SLA</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Origine</strong></td><td><span class=\"kw-def\">nerf périphérique</span> (motoneurone inférieur + fibres sensitives)</td><td>dégénérescence du <span class=\"kw-alerte\">motoneurone supérieur ET inférieur</span></td></tr>\n          <tr><td><strong>Sensibilité</strong></td><td><span class=\"kw-clinique\">atteinte sensitive</span> (sauf cas particuliers)</td><td><span class=\"kw-clinique\">examen sensitif normal</span></td></tr>\n          <tr><td><strong>ROT</strong></td><td><span class=\"kw-clinique\">abolis ou diminués</span></td><td><span class=\"kw-clinique\">vifs et polycinétiques</span> + <span class=\"kw-clinique\">signe de Babinski</span></td></tr>\n          <tr><td><strong>Signes pyramidaux</strong></td><td><span class=\"kw-clinique\">absents</span></td><td>présents (<span class=\"kw-clinique\">Babinski</span>, <span class=\"kw-clinique\">hyperréflexie</span>, <span class=\"kw-clinique\">spasticité</span>)</td></tr>\n          <tr><td><strong>Fasciculations</strong></td><td>possibles, rares</td><td><span class=\"kw-clinique\">très fréquentes</span> (atteinte du <span class=\"kw-def\">motoneurone inférieur</span>)</td></tr>\n          <tr><td><strong>ENMG</strong></td><td>atteinte <span class=\"kw-clinique\">axonale</span> ou <span class=\"kw-clinique\">démyélinisante</span> du nerf</td><td>atteinte <span class=\"kw-clinique\">neurogène pure</span> (corne antérieure), <span class=\"kw-clinique\">sans atteinte sensitive</span></td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Évolution</span></strong></td><td>variable selon étiologie, souvent stabilisable</td><td><span class=\"kw-clinique\">dégénérative</span>, sans traitement curatif</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Piège incontournable.</strong> Devant un <span class=\"kw-clinique\">déficit moteur</span> distal isolé avec amyotrophie et fasciculations : <span class=\"kw-alerte\">si les ROT sont vifs et Babinski +, c'est une SLA</span>, pas une neuropathie périphérique. La <span class=\"kw-def\">NMMBC</span> (obj-7) peut mimer une SLA — ROT parfois vifs malgré l'atrophie — mais sans signe de Babinski.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 92 — <span class=\"kw-clinique\">Déficit moteur</span>-sensitif membres</em></p>","frequence":2},{"id":"96-6","rang":"A","rubrique":"Etiologies","titre":"Connaître les étiologies des principales polyneuropathies axonales longueur-dépendantes","contenu":"<p><span class=\"kw-etio\"><strong>Diabète</strong></span> et <span class=\"kw-etio\"><strong>alcool</strong></span> représentent les <strong>deux causes les plus fréquentes</strong> de polyneuropathie axonale longueur-dépendante.</p>\n      <table >\n        <thead><tr><th>Critère</th><th>Polyneuropathie diabétique</th><th>Polyneuropathie alcoolo-carentielle</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Fréquence</strong></td><td>cause n°1 — <span class=\"kw-chiffre\">~50 %</span> des diabétiques après <span class=\"kw-chiffre\">20 ans</span> d'<span class=\"kw-clinique\">évolution</span> (<span class=\"kw-chiffre\">&gt; 40 %</span> au-delà de <span class=\"kw-chiffre\">25 ans</span>)</td><td>cause n°2 — <span class=\"kw-chiffre\">~10 %</span> des alcooliques chroniques</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Physiopathologie</span></strong></td><td>facteurs métaboliques (<span class=\"kw-bio\">sorbitol</span>, glycation), vasculaires (oblitération des vasa nervorum), inflammatoires</td><td>toxicité directe de l'<span class=\"kw-etio\">alcool</span> + carence en <span class=\"kw-bio\">vitamine B1 (thiamine)</span> ± <span class=\"kw-bio\">folates</span></td></tr>\n          <tr><td><strong>Installation</strong></td><td>lentement progressive (&gt;<span class=\"kw-chiffre\"> 5 ans</span> de <span class=\"kw-etio\">diabète</span>)</td><td>insidieuse, lentement progressive</td></tr>\n          <tr><td><strong>Clinique initiale</strong></td><td><span class=\"kw-clinique\">paresthésies des pieds</span> ; <span class=\"kw-clinique\">hypoesthésie thermoalgique « en chaussettes »</span> d'abord, puis hypoesthésie à tous les modes ; <span class=\"kw-clinique\">aréflexie achilléenne</span> (puis rotulienne) ; douleurs ± allodynie au frottement (questionnaire <span class=\"kw-clinique\">DN4</span>)</td><td><span class=\"kw-clinique\">paresthésies en chaussettes</span> ; <span class=\"kw-clinique\">crampes nocturnes des mollets</span> ; faiblesse à la marche</td></tr>\n          <tr><td><strong>Complications</strong></td><td><span class=\"kw-alerte\">mal perforant plantaire</span> ; <span class=\"kw-clinique\">forme ulcéro-mutilante</span> (déficit thermoalgique sévère + <span class=\"kw-clinique\">ostéolyse</span> + <span class=\"kw-clinique\">arthropathies</span>) ; <span class=\"kw-alerte\">pied de Charcot</span> ; <span class=\"kw-clinique\">dysautonomie</span> (cardiaque, digestive, urinaire, sexuelle)</td><td>hyperpathie nocturne ; troubles trophiques ; <span class=\"kw-clinique\">neuropathie autonome cardiaque</span> (surmortalité)</td></tr>\n          <tr><td><strong>Examens utiles</strong></td><td><span class=\"kw-clinique\">monofilament 10 g</span> (<span class=\"kw-def\">pronostic</span> de plaie) ; <span class=\"kw-bio\">ECG</span> ; ENMG seulement si atypie</td><td>ENMG (anomalies axonales précoces) ; <span class=\"kw-bio\">LCS</span> : <span class=\"kw-bio\">hyperprotéinorachie discrète</span></td></tr>\n          <tr><td><strong>Prise en charge</strong></td><td><span class=\"kw-ttt\">équilibre glycémique</span> (pas de guérison) ; correction des <span class=\"kw-ttt\">facteurs aggravants</span> (carences B1/B12, IRC, alcool, tabac) ; <span class=\"kw-ttt\">antalgiques neuropathiques</span> (<span class=\"kw-ttt\">gabapentine</span>, <span class=\"kw-ttt\">prégabaline</span>, tricycliques, <span class=\"kw-ttt\">duloxétine</span>, <span class=\"kw-ttt\">venlafaxine</span>) ; prévention du pied</td><td><span class=\"kw-ttt\">sevrage alcoolique</span> ; <span class=\"kw-ttt\">recharge B1 parentérale</span> ; régime riche en protéines ; <span class=\"kw-ttt\">antalgiques</span> neuropathiques</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Focus — le pied diabétique</strong></p>\n      <ul>\n        <li><strong><span class=\"kw-def\">Stade</span> initial :</strong> déformation de la voûte plantaire, déplacement antérieur des coussinets, <span class=\"kw-clinique\">orteils en griffe</span>, points d'appui anormaux</li>\n        <li><strong>Pied de Charcot</strong> (neuro-arthropathie) : <span class=\"kw-clinique\">microfractures inaperçues</span> aboutissant à l'effondrement de la voûte plantaire et à la dislocation du tarse — <span class=\"kw-alerte\">risque d'amputation</span></li>\n      </ul>\n      <p><strong>Formes focales et proximales diabétiques (<span class=\"kw-chiffre\">5-15 %</span>)</strong> — plus rares, à dominante motrice, distinctes de la PNP longueur-dépendante :</p>\n      <ul>\n        <li><strong>Amyotrophie diabétique</strong> (plexopathie lombaire) : installation subaiguë ; <span class=\"kw-clinique\">déficit + amyotrophie proximale des MI</span> (psoas, quadriceps, adducteurs), douleurs, ROT abolis aux MI ; peu de signes sensitifs</li>\n        <li><strong>Neuropathies focales/multifocales</strong> : nerfs crâniens (<span class=\"kw-clinique\">oculomoteurs</span>, facial), troncs des membres (ulnaire, médian, fibulaire commun) ; <span class=\"kw-clinique\">cruralgie diabétique</span> (nerf fémoral) à début aigu, déficit quadricipital, abolition du réflexe rotulien</li>\n      </ul>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/96/pied-charcot.png\" alt=\"Pied de Charcot diabétique : effondrement de la voûte plantaire et dislocation tarsienne\" loading=\"lazy\">\n        <figcaption>Pied de Charcot : effondrement de la voûte plantaire et dislocation des os du tarse. Source : fiche source EDN item 96 — Neuropathie diabétique.</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/96/pied-neuropathique-diab.png\" alt=\"Pied neuropathique diabétique : déformation avec appui anormal exposant au mal perforant plantaire\" loading=\"lazy\">\n        <figcaption>Pied neuropathique diabétique : déformation avec acquisition de points d'appui anormaux exposant au mal perforant plantaire. Source : fiche source EDN item 96 — Neuropathie diabétique.</figcaption>\n      </figure>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Une polyneuropathie alcoolique aiguë (installation en &lt;<span class=\"kw-chiffre\"> 24 h</span>) chez un alcoolique dénutri après un épisode <span class=\"kw-etio\">infectieux</span> doit faire évoquer une <span class=\"kw-def\">carence aiguë en B1</span> et chercher une <span class=\"kw-alerte\">encéphalopathie de Gayet-Wernicke</span> associée — recharge B1 parentérale URGENTE.</div>\n      <div class=\"callout callout-warn\"><strong>Piège métabolique.</strong> Chez le diabétique sous <span class=\"kw-ttt\">metformine</span> au long cours, <span class=\"kw-alerte\">la carence en vitamine B12</span> aggrave la polyneuropathie diabétique — risque dose-dépendant de la dose totale cumulée. Doser la <span class=\"kw-bio\">vitamine B12</span> chez tout diabétique avec PNP atypique ou rapidement évolutive.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 247 — <span class=\"kw-etio\">Diabète</span> · 76 — Addiction à l'<span class=\"kw-etio\">alcool</span></em></p>","frequence":1,"liens":[{"href":"https://radiopaedia.org/articles/charcot-joint","label":"Radiopaedia : Charcot joint (arthropathie neurogène)"}]},{"id":"96-7","rang":"B","rubrique":"Etiologies","titre":"Connaître les étiologies des polyneuropathies axonales longueur-dépendantes plus rares","contenu":"<p>En l'absence de <span class=\"kw-etio\">diabète</span> et d'<span class=\"kw-etio\">alcool</span>, d'autres causes plus rares de polyneuropathie axonale longueur-dépendante doivent être recherchées.</p>\n      <table >\n        <thead><tr><th>Étiologie</th><th>Particularités · orientation</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\"><strong>Amylose</strong></span></td><td>transthyrétine mutée (Val30Met) ou amylose AL sur gammapathie monoclonale ; <span class=\"kw-clinique\">dysautonomie riche</span> ; <span class=\"kw-clinique\">syndrome du canal carpien</span> ; contexte familial possible — <span class=\"kw-bio\">biopsie</span> (nerf, glandes salivaires, graisse) + test <span class=\"kw-etio\">génétique</span> transthyrétine</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Médicaments</strong></span></td><td><span class=\"kw-ttt\">cytostatiques</span> (vincristine, sels de platine) ; <span class=\"kw-ttt\">thalidomide</span> ; <span class=\"kw-ttt\">amiodarone</span> ; <span class=\"kw-ttt\">nitrofurantoïne</span> ; <span class=\"kw-ttt\">disulfirame</span> ; <span class=\"kw-ttt\">isoniazide</span> ; <span class=\"kw-ttt\">chloroquine</span> ; <span class=\"kw-ttt\">antirétroviraux</span> ; <span class=\"kw-ttt\">métronidazole</span></td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Toxiques industriels</strong></span></td><td>benzène ; métaux lourds (plomb, arsenic) — rares, contexte professionnel</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>VIH</strong></span></td><td>polyneuropathie sensitive de la phase tardive de l'infection</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Dysthyroïdie</strong></span></td><td><span class=\"kw-def\">hypothyroïdie</span> surtout (rare)</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Insuffisance rénale chronique</strong></span></td><td>polyneuropathie urémique : amyotrophie, crampes, syndrome des jambes sans repos</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Carences vitaminiques</strong></span></td><td><span class=\"kw-bio\">B12</span> (+ <span class=\"kw-clinique\">syndrome cordonal postérieur</span>) ; <span class=\"kw-bio\">B1</span> ; <span class=\"kw-bio\">B6</span> (excès paradoxalement neurotoxique)</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Maladies systémiques</strong></span></td><td><span class=\"kw-def\">lupus</span> ; vascularites ; <span class=\"kw-clinique\">syndrome de Gougerot</span>-Sjögren (rares en forme purement axonale)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Devant une polyneuropathie axonale sans cause évidente (ni <span class=\"kw-etio\">diabète</span>, ni <span class=\"kw-etio\">alcool</span>), élargir l'interrogatoire <span class=\"kw-def\">médicamenteux</span> et demander <span class=\"kw-bio\">immunofixation, TSH, vitamine B12, créatinine, sérologie VIH, FAN</span>. Si le bilan est négatif et le caractère familial → test <span class=\"kw-etio\">génétique</span> transthyrétine (amylose).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 169 — <span class=\"kw-etio\">VIH</span> · 264 — <span class=\"kw-def\">Insuffisance rénale chronique</span> · 194 — <span class=\"kw-def\">Lupus</span> - SAPL</em></p>","frequence":0},{"id":"96-8","rang":"B","rubrique":"Etiologies","titre":"Connaître les étiologies des principales polyneuropathies démyélinisantes","contenu":"<p>Les polyneuropathies démyélinisantes sont, dans leur quasi-totalité, d'origine <span class=\"kw-def\">dysimmunitaire</span> — ce qui en fait la clé thérapeutique (immunoglobulines IV, <span class=\"kw-ttt\">corticoïdes</span>, plasmaphérèses).</p>\n      <table >\n        <thead><tr><th>Forme</th><th>Clinique</th><th>Paraclinique · traitement</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Polyradiculonévrite aiguë inflammatoire</strong></span> (<span class=\"kw-etio\">Guillain-Barré</span>)</td>\n            <td>installation aiguë (<span class=\"kw-chiffre\">&lt; 4 sem.</span>), bilatérale symétrique, ascendante, <span class=\"kw-clinique\">aréflexie diffuse</span> ; atteinte des nerfs crâniens et <span class=\"kw-alerte\">respiratoire</span> possibles</td>\n            <td><span class=\"kw-bio\">dissociation albumino-cytologique du LCS</span> ; ENMG démyélinisant — <span class=\"kw-ttt\">Ig IV ou plasmaphérèse</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>PIDC</strong></span> (polyradiculoneuropathie <span class=\"kw-etio\">inflammatoire</span> démyélinisante chronique)</td>\n            <td>forme chronique (<span class=\"kw-chiffre\">&gt; 8 sem.</span>), <span class=\"kw-clinique\">évolution</span> par poussées ou progressive</td>\n            <td><span class=\"kw-bio\">hyperprotéinorachie</span> ; ENMG démyélinisant chronique avec blocs — <span class=\"kw-ttt\">corticoïdes + Ig IV</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Neuropathie à IgM monoclonale anti-MAG</strong></span></td>\n            <td>&gt;<span class=\"kw-chiffre\"> 50 ans</span> ; <span class=\"kw-clinique\">ataxie sensitive</span> ; tremblement des mains ; peu de <span class=\"kw-clinique\">déficit moteur</span></td>\n            <td><span class=\"kw-bio\">pic IgM monoclonal (&lt; 10 g/L)</span> ; <span class=\"kw-bio\">AC anti-MAG</span> — <span class=\"kw-ttt\">rituximab</span>, immunomodulation</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>NMMBC</strong></span> (neuropathie motrice multifocale à blocs persistants)</td>\n            <td>homme &lt;<span class=\"kw-chiffre\"> 50 ans</span> ; <span class=\"kw-clinique\">asymétrique</span>, prédominant aux MS ; atteinte motrice pure ; peut mimer une SLA</td>\n            <td><span class=\"kw-clinique\">blocs de conduction persistants à <span class=\"kw-chiffre\">3 mois</span></span> ; <span class=\"kw-bio\">AC anti-GM1</span> — <span class=\"kw-ttt\">Ig IV</span> ; <span class=\"kw-ci\">les corticoïdes peuvent aggraver</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Neuropathies héréditaires (Charcot-Marie-Tooth).</strong> Les plus fréquentes des neuropathies héréditaires : duplication du gène <span class=\"kw-bio\">PMP22</span> (chromosome 17, formes dominantes) ou anomalie de la <span class=\"kw-bio\">connexine 32</span> (forme liée à l'X). Prédominance <span class=\"kw-clinique\">motrice</span> : <span class=\"kw-clinique\">pieds creux</span>, <span class=\"kw-clinique\">atrophie des mollets</span>, peu de symptomatologie sensitive — confirmation par test <span class=\"kw-etio\">génétique</span>.</p>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span>.</strong> Devant un <span class=\"kw-clinique\">déficit moteur</span> ascendant rapide avec aréflexie diffuse = <span class=\"kw-alerte\">Guillain-Barré jusqu'à preuve du contraire</span> → <span class=\"kw-alerte\">hospitalisation</span>, ENMG, <span class=\"kw-bio\">LCS</span>, <span class=\"kw-def\">surveillance</span> respiratoire continue. Cf. item 97.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 97 — Polyradiculonévrite aigue <span class=\"kw-etio\">inflammatoire</span></em></p>","frequence":0},{"id":"96-9","rang":"B","rubrique":"Etiologies","titre":"Connaître les étiologies des principales neuronopathies","contenu":"<p>Les <span class=\"kw-def\"><strong>neuronopathies</strong></span> correspondent à l'atteinte du corps cellulaire du neurone — <span class=\"kw-def\">sensitif</span> (ganglion rachidien) ou <span class=\"kw-def\">moteur</span> (corne antérieure). Le mécanisme est le plus souvent <span class=\"kw-def\">dysimmunitaire</span> ou <span class=\"kw-etio\">paranéoplasique</span>.</p>\n      <p><strong>Neuronopathies sensitives (ganglionopathies)</strong> — <span class=\"kw-clinique\">atteinte exclusivement sensitive</span>, <span class=\"kw-clinique\">non longueur-dépendante</span> (cf. obj-3).</p>\n      <table >\n        <thead><tr><th>Étiologie</th><th>Orientation</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\"><strong>Cancer du poumon à petites cellules</strong></span></td><td>syndrome <span class=\"kw-bio\">anti-Hu</span> — bilan : <span class=\"kw-imagerie\">TDM thoracique</span>, <span class=\"kw-imagerie\">TEP-TDM</span>, <span class=\"kw-bio\">biopsie</span>, <span class=\"kw-bio\">AC anti-neuronaux</span></td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Syndrome de Gougerot-Sjögren</strong></span></td><td><span class=\"kw-clinique\">syndrome sec</span> oculaire et buccal ; <span class=\"kw-bio\">BGSA</span> ; <span class=\"kw-bio\">AC anti-SSA / anti-SSB</span></td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Dysimmunitaire</strong></span></td><td>sans cause identifiée</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Toxique</strong></span></td><td><span class=\"kw-ttt\">sels de platine</span> (<span class=\"kw-ttt\">chimiothérapie</span>)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Neuronopathies motrices</strong> — atteinte de la corne antérieure (<span class=\"kw-def\">motoneurone inférieur pur</span>). La <span class=\"kw-etio\">SLA</span> en est le cadre lorsqu'une atteinte du <span class=\"kw-def\">motoneurone supérieur</span> s'y associe. En l'absence de <span class=\"kw-clinique\">signe pyramidal</span> : <span class=\"kw-etio\">amyotrophie spinale</span> (<span class=\"kw-etio\">génétique</span>) ou <span class=\"kw-etio\">séquelles de poliomyélite</span>.</p>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Toute neuronopathie sensitive impose un bilan <span class=\"kw-etio\">paranéoplasique</span> : <span class=\"kw-imagerie\">TDM thoracique + TEP-TDM</span>, <span class=\"kw-bio\">AC anti-Hu</span>. Le délai entre la neuronopathie et la découverte du cancer peut atteindre <span class=\"kw-chiffre\">1 à 2 ans</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 309 — Tumeurs du poumon</em></p>","frequence":0},{"id":"96-10","rang":"A","rubrique":"Etiologies","titre":"Connaître les étiologies des principales mononeuronopathies multiples","contenu":"<p>La <span class=\"kw-def\"><strong>mononeuropathie multiple</strong></span> est due à une <span class=\"kw-etio\">vascularite</span> des vasa nervorum (processus <span class=\"kw-etio\">ischémique</span>) qui touche plusieurs troncs nerveux.</p>\n      <table >\n        <thead><tr><th>Cadre étiologique</th><th>Causes</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Vascularites primitives</strong></span></td>\n            <td><strong>Vaisseaux moyens :</strong> <span class=\"kw-etio\">périartérite noueuse (PAN)</span><br><strong>Petits vaisseaux :</strong> <span class=\"kw-etio\">vascularites à ANCA</span> (Wegener, Churg-Strauss, MPA) ; <span class=\"kw-etio\">cryoglobulinémie essentielle</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Vascularites secondaires</strong></span></td>\n            <td><span class=\"kw-etio\">cryoglobulinémie</span> (souvent <span class=\"kw-etio\">VHC</span>) ; <span class=\"kw-etio\">polyarthrite rhumatoïde</span> ; <span class=\"kw-etio\">lupus systémique</span> ; <span class=\"kw-etio\">Gougerot-Sjögren</span> ; <span class=\"kw-etio\">VIH</span></td>\n          </tr>\n          <tr><td><span class=\"kw-etio\"><strong>Diabète</strong></span></td><td>atteinte surtout aux zones de compression nerveuse (tunnels)</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Sarcoïdose</strong></span></td><td>peut donner des mononeuropathies multiples</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Lèpre</strong></span></td><td>neuropathie la plus fréquente dans le monde (rare en France), à grande prédominance sensitive</td></tr>\n          <tr><td><span class=\"kw-etio\"><strong>Vascularite paranéoplasique</strong></span></td><td>rare, satellite d'un cancer</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Topographie.</strong> Le <span class=\"kw-clinique\">nerf fibulaire commun</span> est le tronc le plus fréquemment atteint ; une atteinte des <span class=\"kw-clinique\">nerfs crâniens</span> (<span class=\"kw-clinique\">trijumeau</span>, <span class=\"kw-clinique\">oculomoteurs</span>) est possible, surtout au cours du <span class=\"kw-etio\">diabète</span>.</p>\n      <p><strong>Signes d'alerte d'une maladie systémique</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Fièvre</span>, <span class=\"kw-clinique\">amaigrissement</span>, <span class=\"kw-clinique\">myalgies</span>, <span class=\"kw-clinique\">arthralgies</span></li>\n        <li><span class=\"kw-clinique\">Livedo</span>, <span class=\"kw-clinique\">purpura</span> cutané</li>\n        <li>Atteinte rénale : <span class=\"kw-def\">HTA</span>, <span class=\"kw-clinique\">hématurie</span>, <span class=\"kw-bio\">protéinurie</span></li>\n        <li>Atteinte ORL (Wegener), pulmonaire (hémoptysies)</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span> diagnostique et thérapeutique.</strong> Toute mononeuropathie multiple doit faire évoquer une <span class=\"kw-etio\">vascularite</span> et déclencher un bilan systémique en urgence (cf. obj-10). <span class=\"kw-alerte\">Le retard diagnostique = séquelles motrices définitives.</span></div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 193 — <span class=\"kw-etio\">Vascularite</span> systémique · 247 — <span class=\"kw-etio\">Diabète</span> · 211 — Sarcoïdose</em></p>","frequence":0},{"id":"96-11","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître l’urgence du diagnostic et de la prise en charge des mononeuropathies multiples","contenu":"<p>La mononeuropathie multiple est une <span class=\"kw-alerte\">urgence neurologique et systémique</span>. Le retard diagnostique entraîne des <span class=\"kw-alerte\">séquelles motrices définitives</span> par dégénérescence axonale <span class=\"kw-etio\">ischémique</span>.</p>\n      <table >\n        <thead><tr><th>Pilier</th><th>Conduite à tenir en <span class=\"kw-alerte\">urgence</span></th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\"><strong>Clinique</strong></span></td><td>installation aiguë/subaiguë ; atteinte tronculaire <span class=\"kw-clinique\">asymétrique et asynchrone</span> ; signes systémiques (<span class=\"kw-clinique\">fièvre</span>, livedo, <span class=\"kw-clinique\">purpura</span>, atteinte rénale ou ORL)</td></tr>\n          <tr><td><span class=\"kw-bio\"><strong>Biologie urgente</strong></span></td><td><span class=\"kw-bio\">NFS, VS, CRP</span> ; <span class=\"kw-bio\">créatinine, protéinurie des 24 h</span> ; <span class=\"kw-bio\">sérologies</span> <span class=\"kw-bio\">VHB / VHC / VIH</span> ; <span class=\"kw-bio\">complément (C3, C4, CH50)</span> ; <span class=\"kw-bio\">facteur rhumatoïde</span> ; <span class=\"kw-bio\">cryoglobulinémie</span> ; <span class=\"kw-bio\">AC anti-noyaux, anti-ADN, anti-antigènes solubles</span> ; <span class=\"kw-bio\">pANCA / cANCA</span></td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>ENMG</strong></span></td><td>confirme une atteinte pluritronculaire <span class=\"kw-clinique\">axonale asymétrique</span> ; oriente le choix du nerf à biopsier</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Biopsie neuromusculaire</strong></span></td><td>examen clé pour chercher la <span class=\"kw-etio\">vascularite</span> (sauf cause diabétique évidente) : <span class=\"kw-alerte\">nécrose fibrinoïde</span> de la paroi des artères de moyen calibre + infiltrat <span class=\"kw-etio\">inflammatoire</span></td></tr>\n          <tr><td><span class=\"kw-ttt\"><strong>Traitement</strong></span></td><td><span class=\"kw-ttt\">corticoïdes</span> ± <span class=\"kw-ttt\">immunosuppresseurs</span> (cyclophosphamide, <span class=\"kw-ttt\">rituximab</span> selon la <span class=\"kw-etio\">vascularite</span>), en <span class=\"kw-alerte\">urgence</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Cas particulier :</strong> chez le <span class=\"kw-etio\">diabétique</span> avec contexte évident, la <span class=\"kw-bio\">biopsie</span> neuromusculaire n'est pas nécessaire.</p>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Drapeau rouge</span>.</strong> Devant une <span class=\"kw-clinique\">multinévrite + fièvre + livedo + atteinte rénale</span> : suspicion de <span class=\"kw-alerte\">vascularite systémique nécrosante</span> (PAN, <span class=\"kw-bio\">ANCA</span>, cryoglobulinémie) → <span class=\"kw-alerte\">hospitalisation</span>, <span class=\"kw-bio\">biopsie</span> neuromusculaire, <span class=\"kw-ttt\">corticothérapie</span> en bolus IV.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 97 — Polyradiculonévrite aigue <span class=\"kw-etio\">inflammatoire</span> · 193 — <span class=\"kw-etio\">Vascularite</span> systémique</em></p>","frequence":0},{"id":"96-12","rang":"B","rubrique":"Examens complémentaires","titre":"Avoir une stratégie d’utilisation des examens complémentaires","contenu":"<p>La stratégie d'exploration repose sur <strong>4 examens hiérarchisés</strong> : ENMG (toujours), <span class=\"kw-bio\">LCS</span> (selon le contexte), <span class=\"kw-bio\">biopsie</span> (selon le contexte) et biologie systématique.</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Apport · indications · pièges</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>ENMG</strong></span></td>\n            <td><strong>Apport :</strong> distingue axonal / démyélinisant / neuronopathie, précise la topographie, quantifie la sévérité<br><strong>Indication :</strong> systématique, sauf cas évident<br><strong>Pièges :</strong> peu spécifique chez le diabétique ancien (anormal après <span class=\"kw-chiffre\">10-15 ans</span>) ; <span class=\"kw-alerte\">normal en cas d'atteinte isolée des petites fibres</span> (neuropathie douloureuse pure)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\"><strong>Étude du LCS</strong></span></td>\n            <td><strong>Apport :</strong> argument pour une atteinte proximale — <span class=\"kw-bio\">hyperprotéinorachie isolée</span> = PRN ou <span class=\"kw-etio\">diabète</span> ; <span class=\"kw-bio\">réaction cellulaire</span> = <span class=\"kw-etio\">paranéoplasique</span> ; <span class=\"kw-def\">méningite</span> = néoplasie/hémopathie<br><strong>Indication :</strong> PRN, neuronopathies sensitives<br><strong>Piège :</strong> inutile sur une PNP banale longueur-dépendante</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Biopsie neuromusculaire</strong></span></td>\n            <td><strong>Apport :</strong> confirme <span class=\"kw-etio\">vascularite</span> (<span class=\"kw-alerte\">nécrose fibrinoïde</span> + infiltrat), amylose (dépôts), PIDC (démyélinisation)<br><strong>Indication :</strong> suspicion de <span class=\"kw-etio\">vascularite</span>, neuropathie évolutive sans cause<br><strong>Pièges :</strong> jamais en 1<sup>re</sup> intention ; <span class=\"kw-ci\">toujours un nerf sensitif atteint</span> (sural, fibulaire superficiel) ; <span class=\"kw-ci\">jamais un nerf moteur</span> ; complications : hypoesthésie séquellaire, troubles de cicatrisation</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\"><strong>Biologie systématique</strong></span></td>\n            <td><strong>Apport :</strong> <span class=\"kw-def\">dépistage</span> des causes traitables<br><strong>Bilan :</strong> <span class=\"kw-bio\">NFS, VS, CRP, ionogramme</span> ; <span class=\"kw-bio\">glycémie + HbA1c</span> ; <span class=\"kw-bio\">TSH</span> ; <span class=\"kw-bio\">immunofixation des Ig sériques</span> ; <span class=\"kw-bio\">créatinine</span> ; <span class=\"kw-bio\">sérologies</span> <span class=\"kw-etio\">VHB</span>/VHC/VIH selon le contexte</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Monofilament 10 g</strong></span></td>\n            <td><strong>Apport :</strong> test de <span class=\"kw-def\">dépistage</span> du <span class=\"kw-alerte\">risque de plaie du pied diabétique</span> — plus pronostique que diagnostique<br><strong>Indication :</strong> systématique à chaque consultation chez le diabétique<br><strong>Piège :</strong> ne détecte que les <span class=\"kw-clinique\">grosses fibres</span> — <span class=\"kw-alerte\">laisse passer <span class=\"kw-chiffre\">~30 %</span> des neuropathies périphériques</span> ; en cas de doute, compléter par <span class=\"kw-clinique\">DN4</span> + recherche d'autres atteintes sensitives</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Examens spécialisés selon le contexte</strong></p>\n      <table >\n        <thead><tr><th>Examen</th><th>Indication · contexte</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\"><strong>Test génétique</strong></span> (<span class=\"kw-bio\">transthyrétine</span>, <span class=\"kw-bio\">PMP22</span>, <span class=\"kw-bio\">connexine 32</span>)</td><td>forme familiale (amylose, Charcot-Marie-Tooth)</td></tr>\n          <tr><td><span class=\"kw-bio\"><strong>Auto-anticorps</strong></span> (<span class=\"kw-bio\">anti-MAG</span>, <span class=\"kw-bio\">anti-GM1</span>, <span class=\"kw-bio\">anti-Hu</span>)</td><td>selon l'orientation étiologique (anti-MAG, NMMBC, neuronopathie <span class=\"kw-etio\">paranéoplasique</span>)</td></tr>\n          <tr><td><span class=\"kw-imagerie\"><strong>TDM thoracique + TEP-TDM</strong></span></td><td>suspicion <span class=\"kw-etio\">paranéoplasique</span> (neuronopathie sensitive, AC anti-Hu)</td></tr>\n          <tr><td><span class=\"kw-imagerie\"><strong>Échographie haute fréquence</strong></span> des nerfs périphériques</td><td>en développement, accès limité</td></tr>\n          <tr><td><span class=\"kw-clinique\"><strong>Tests dysautonomiques</strong></span> (FC respiration profonde, Valsalva, orthostatisme)</td><td>suspicion de <span class=\"kw-clinique\">dysautonomie diabétique</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Discriminant clé.</strong> Devant une PNP banale longueur-dépendante (<span class=\"kw-etio\">diabète</span> probable) : <span class=\"kw-bio\">glycémie + HbA1c + TSH + B12 + créatinine + immunofixation</span> suffisent en 1<sup>re</sup> intention. <span class=\"kw-alerte\">Ne pas demander d'emblée</span> <span class=\"kw-bio\">LCS</span>, <span class=\"kw-bio\">biopsie</span> ou test <span class=\"kw-etio\">génétique</span> — seulement si le bilan est négatif ou la présentation atypique.</div>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> 4 mots-clés EDN : ENMG d'abord ; <span class=\"kw-ttt\">biopsie</span> = vascularite ; <span class=\"kw-bio\">LCS</span> = PRN ou <span class=\"kw-etio\">paranéoplasique</span> ; test génétique = formes familiales.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 134 — Bases neurophysiologiques de la douleur · 247 — <span class=\"kw-etio\">Diabète</span></em></p>","frequence":4}],"astuces":[{"type":"info","titre":"Astuces & pièges","contenu":"<ul>\n<li><strong>Mononeuropathie multiple = vascularite</strong> jusqu'à preuve du contraire → <span class=\"kw-alerte\">urgence</span>.</li>\n<li><strong>Présence de troubles sensitifs = exclut la SLA</strong>.</li>\n<li><strong>ENMG à différer <span class=\"kw-chiffre\">> 3 semaines</span></strong> pour voir la dénervation.</li>\n<li><strong>SGB :</strong> dissociation albumino-cytologique au <span class=\"kw-bio\">LCS</span> (protéines ↑ sans cellules) — pas de PL avant <span class=\"kw-chiffre\">J7</span>.</li>\n<li><strong><span class=\"kw-etio\">Diabète</span></strong> = 1<sup>re</sup> cause de polyneuropathie en France ; <span class=\"kw-def\">dépistage</span> annuel par monofilament <span class=\"kw-chiffre\">10 g</span>.</li>\n</ul>"}],"strategie":{"urgence":"<p><strong>Mononeuropathie multiple <span class=\"q\">— <span class=\"kw-alerte\">urgence</span> diagnostique <em>et</em> thérapeutique</span></strong></p><p>bilan systémique en <span class=\"kw-alerte\">urgence</span> · <span class=\"kw-bio\">biopsie neuromusculaire</span> · <span class=\"kw-ttt\">corticothérapie</span> ± <span class=\"kw-ttt\">immunosuppresseurs</span></p><ul><li><span class=\"kw-etio\">Vascularite</span> des vasa nervorum jusqu'à preuve du contraire</li><li><span class=\"kw-alerte\">Le retard = séquelles motrices définitives</span> (dégénérescence axonale <span class=\"kw-etio\">ischémique</span>)</li></ul><p><strong>Polyradiculonévrite aiguë <span class=\"q\">(Guillain-Barré)</span></strong></p><p><span class=\"kw-alerte\">hospitalisation</span> · <span class=\"kw-bio\">LCS</span> · <span class=\"kw-imagerie\">ENMG</span> · <span class=\"kw-alerte\">surveillance respiratoire continue</span> (item 97)</p><ul><li><span class=\"kw-clinique\">Déficit moteur ascendant rapide</span> + <span class=\"kw-clinique\">aréflexie diffuse</span></li></ul><p><strong>PNP alcoolique aiguë <span class=\"q\">(&lt;<span class=\"kw-chiffre\"> 24 h</span>, sur dénutri)</span></strong></p><p><span class=\"kw-ttt\">recharge B1 parentérale URGENTE</span>, avant tout apport glucosé</p><ul><li><span class=\"kw-def\">Carence aiguë en B1</span> → risque d'<span class=\"kw-alerte\">encéphalopathie de Gayet-Wernicke</span></li></ul><p><strong>Neuronopathie sensitive <span class=\"q\">(sensitive pure, non longueur-dépendante, MS d'emblée)</span></strong></p><p><span class=\"kw-alerte\">éliminer un cancer du poumon à petites cellules</span> (<span class=\"kw-bio\">AC anti-Hu</span>, <span class=\"kw-imagerie\">TDM thoracique</span>)</p>","redflags":"<ul><li><span class=\"kw-alerte\">Multinévrite + fièvre + livedo + purpura + atteinte rénale</span> → vascularite systémique nécrosante (<span class=\"kw-etio\">PAN</span>, <span class=\"kw-bio\">ANCA</span>, cryoglobulinémie)</li><li><span class=\"kw-alerte\">Déficit moteur ascendant rapide + aréflexie diffuse</span> → <span class=\"kw-etio\">Guillain-Barré</span> jusqu'à preuve du contraire</li><li><span class=\"kw-alerte\">Atteinte respiratoire / troubles de déglutition</span> sur PRN aiguë ascendante</li><li>Atteinte <span class=\"kw-clinique\">sensitive pure, non longueur-dépendante, d'emblée aux MS</span> → ganglionopathie <span class=\"kw-etio\">paranéoplasique</span></li><li>Déficit moteur distal + amyotrophie + fasciculations MAIS <span class=\"kw-clinique\">ROT vifs + Babinski</span> → <span class=\"kw-etio\">SLA</span> (ce n'est pas une neuropathie périphérique)</li><li>PNP <span class=\"kw-clinique\">rapidement évolutive ou atypique</span> chez le diabétique → chercher une autre cause (<span class=\"kw-bio\">B12</span> sous <span class=\"kw-ttt\">metformine</span>, dysimmunitaire)</li><li><span class=\"kw-alerte\">Mal perforant plantaire / pied de Charcot</span> chez le diabétique → risque d'amputation</li></ul>","principes":"<p><strong>Règle d'or :</strong> le traitement est avant tout <span class=\"kw-ttt\">étiologique</span>. Les <span class=\"kw-def\">PNP axonales longueur-dépendantes</span> (<span class=\"kw-etio\">diabète</span>, alcool) ne guérissent pas → on <strong>stabilise</strong> ; les <span class=\"kw-def\">neuropathies dysimmunitaires</span> (démyélinisantes, vascularites) se <strong>traitent</strong> (Ig, <span class=\"kw-ttt\">corticoïdes</span>, <span class=\"kw-ttt\">immunosuppresseurs</span>).</p><p><strong>PNP diabétique</strong></p><ul><li><span class=\"kw-ttt\">Équilibre glycémique</span> (pas de guérison)</li><li>Correction des facteurs aggravants (<span class=\"kw-bio\">B1/B12</span>, IRC, alcool, tabac)</li><li>Surveiller la <span class=\"kw-bio\">B12</span> sous <span class=\"kw-ttt\">metformine</span></li></ul><p><strong>PNP alcoolo-carentielle</strong></p><ul><li><span class=\"kw-ttt\">Sevrage alcoolique</span></li><li><span class=\"kw-ttt\">Recharge B1 parentérale</span></li><li>Régime hyperprotidique</li></ul><p><strong>Douleur neuropathique <span class=\"q\">(<span class=\"kw-clinique\">DN4</span> +)</span></strong></p><ul><li><span class=\"kw-ttt\">Antalgiques neuropathiques</span> : <span class=\"kw-ttt\">gabapentine</span>, <span class=\"kw-ttt\">prégabaline</span>, tricycliques, <span class=\"kw-ttt\">duloxétine</span>, <span class=\"kw-ttt\">venlafaxine</span></li></ul><p><strong>Neuropathies démyélinisantes dysimmunitaires</strong></p><ul><li><span class=\"kw-ttt\">Ig IV</span>, <span class=\"kw-ttt\">corticoïdes</span>, <span class=\"kw-ttt\">plasmaphérèses</span></li><li>PIDC = <span class=\"kw-ttt\">corticoïdes</span> + Ig IV</li><li>Anti-MAG = <span class=\"kw-ttt\">rituximab</span></li></ul><p><strong>NMMBC</strong></p><ul><li><span class=\"kw-ttt\">Ig IV</span></li><li><span class=\"kw-ci\">Les corticoïdes peuvent aggraver</span></li></ul><p><strong>Mononeuropathie multiple / vascularite</strong></p><ul><li><span class=\"kw-ttt\">Corticoïdes</span> ± <span class=\"kw-ttt\">immunosuppresseurs</span> (cyclophosphamide, <span class=\"kw-ttt\">rituximab</span>) en <span class=\"kw-alerte\">urgence</span></li></ul><p><strong>Cause médicamenteuse / <span class=\"kw-etio\">toxique</span></strong></p><ul><li><span class=\"kw-ttt\">Arrêt du neurotoxique</span> (<span class=\"kw-ttt\">chimiothérapie</span>, <span class=\"kw-ttt\">isoniazide</span>, <span class=\"kw-ttt\">amiodarone</span>…)</li></ul><p><strong>Pied diabétique</strong></p><ul><li><span class=\"kw-clinique\">Monofilament 10 g</span> à chaque consultation</li><li>Éducation · chaussage adapté · soins podologiques</li><li>Prévention du mal perforant et du pied de Charcot</li></ul>"},"liensGlobaux":[{"href":"https://www.cen-neurologie.fr/second-cycle/radiculalgies-et-syndromes-canalaires-neuropathies-peripheriques-polyradiculonevrite-aigue-inflammatoire-syndrome-de-guillain-barre","label":"Collège CEN — Neuropathies périphériques"},{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/33.%20Paralysies%20extensives.pdf","label":"Collège Réa CE-MIR — Paralysies extensives (PDF)"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Déficit neuro distal — suspicion de neuropathie périphérique — Étape 1 — est-ce bien périphérique ? (ROT, signe pyramidal)","detail":"<h4>Démarche diagnostique — neuropathie périphérique — Syndrome neurogène périphérique → topographie → mécanisme / étiologie</h4>","branches":[{"to":"t-sla","label":"ROT vifs/polycinétiques + Babinski + spasticité","color":"red"},{"to":"q-topo","label":"Syndrome neurogène périphérique (ROT abolis/diminués, amyotrophie, pas de signe pyramidal)","color":"amber"}]},{"id":"t-sla","kind":"terminal","label":"SLA — atteinte du motoneurone supérieur (pas une neuropathie périphérique)","color":"red","detail":"<h4>Discriminant</h4><ul><li><span class=\"kw-clinique\">Signe pyramidal</span> (Babinski, hyperréflexie, spasticité) + <span class=\"kw-clinique\">examen sensitif normal</span> = atteinte du <span class=\"kw-def\">motoneurone supérieur</span> → SLA, pas une neuropathie périphérique</li></ul><h4>Piège</h4><ul><li>La <span class=\"kw-def\">NMMBC</span> peut mimer une SLA (déficit moteur pur asymétrique des MS, fasciculations) mais <span class=\"kw-alerte\">sans Babinski</span> + <span class=\"kw-clinique\">blocs de conduction persistants</span> + <span class=\"kw-bio\">AC anti-GM1</span> → répond aux <span class=\"kw-ttt\">Ig IV</span></li></ul><h4>Renvoi</h4><ul><li>obj-4 · Item 92 — Déficit moteur/sensitif</li></ul>"},{"id":"q-topo","kind":"decision","label":"Étape 2 — quelle topographie ? — Symétrique/asymétrique · proximal/distal · racines/troncs · sensitif/moteur","branches":[{"to":"q-pnp","label":"Symétrique, distale, longueur-dépendante (gants & chaussettes), sensitive ≫ motrice","color":"amber"},{"to":"t-mnm","label":"Asymétrique, tronculaire multiple, asynchrone","color":"red"},{"to":"t-mn","label":"Focale, un seul tronc nerveux","color":"blue"},{"to":"q-prn","label":"Proximale ET distale, racines + troncs + nerfs crâniens, aréflexie diffuse","color":"amber"},{"to":"t-ganglio","label":"Sensitive pure, non longueur-dépendante, d'emblée MS + MI","color":"amber"}]},{"id":"q-pnp","kind":"decision","label":"Polyneuropathie (PNP) — quel mécanisme à l'ENMG ? — Axonale vs démyélinisante","branches":[{"to":"t-pnp-diab-alcool","label":"Axonale + diabète ou alcool évident","color":"green"},{"to":"t-pnp-axonale-rare","label":"Axonale sans diabète ni alcool","color":"amber"},{"to":"t-pnp-demye","label":"Démyélinisante (ralentissement, blocs de conduction)","color":"amber"}]},{"id":"t-pnp-diab-alcool","kind":"terminal","label":"PNP axonale longueur-dépendante — diabète / alcool (≈ 90 %)","color":"green","detail":"<h4>Causes</h4><ul><li><span class=\"kw-etio\">Diabète</span> = cause n°1 (~<span class=\"kw-chiffre\">50 %</span> après <span class=\"kw-chiffre\">20 ans</span> d'<span class=\"kw-clinique\">évolution</span>)</li><li><span class=\"kw-etio\">Alcool</span> = cause n°2 (~<span class=\"kw-chiffre\">10 %</span>) + carence <span class=\"kw-bio\">B1</span></li></ul><h4>Bilan minimal</h4><ul><li><span class=\"kw-bio\">glycémie + HbA1c</span> · <span class=\"kw-bio\">gamma-GT + VGM</span> + interrogatoire alcool · revue des médicaments. <span class=\"kw-imagerie\">ENMG</span> seulement si atypie</li></ul><h4>PEC</h4><ul><li><span class=\"kw-ttt\">équilibre glycémique</span> / <span class=\"kw-ttt\">sevrage + B1</span> ; <span class=\"kw-ttt\">antalgiques neuropathiques</span> ; prévention du pied (<span class=\"kw-clinique\">monofilament</span>)</li></ul><h4>Renvoi</h4><ul><li>obj-5 · Item 247 — <span class=\"kw-etio\">Diabète</span> · Item 76 — Alcool</li></ul>"},{"id":"t-pnp-axonale-rare","kind":"terminal","label":"PNP axonale sans cause évidente → bilan étiologique élargi","color":"amber","detail":"<h4>Bilan</h4><ul><li><span class=\"kw-bio\">immunofixation</span> · <span class=\"kw-bio\">TSH</span> · <span class=\"kw-bio\">B12</span> · <span class=\"kw-bio\">créatinine</span> · <span class=\"kw-bio\">sérologie VIH</span> · <span class=\"kw-bio\">FAN</span> ; revue médicaments/toxiques (cytostatiques, <span class=\"kw-ttt\">isoniazide</span>, <span class=\"kw-ttt\">amiodarone</span>…)</li></ul><h4>Si négatif</h4><ul><li>caractère familial → <span class=\"kw-bio\">test génétique transthyrétine</span> (amylose) / <span class=\"kw-bio\">PMP22</span> (Charcot-Marie-Tooth)</li></ul><h4>Renvoi</h4><ul><li>obj-6</li></ul>"},{"id":"t-pnp-demye","kind":"terminal","label":"PNP démyélinisante → origine dysimmunitaire","color":"amber","detail":"<h4>Clé</h4><ul><li>quasi toujours <span class=\"kw-def\">dysimmunitaire</span> = clé thérapeutique (immunomodulation)</li></ul><h4>Formes</h4><ul><li><span class=\"kw-def\">PIDC</span> (chronique &gt; 8 sem, <span class=\"kw-bio\">hyperprotéinorachie</span>) → <span class=\"kw-ttt\">corticoïdes + Ig IV</span></li><li>Anti-MAG (&gt;<span class=\"kw-chiffre\"> 50 ans</span>, ataxie sensitive, <span class=\"kw-bio\">IgM monoclonale</span>) → <span class=\"kw-ttt\">rituximab</span></li></ul><h4>Renvoi</h4><ul><li>obj-7</li></ul>"},{"id":"t-mnm","kind":"terminal","label":"URGENCE — Mononeuropathie multiple → vascularite ?","color":"red","detail":"<h4><span class=\"kw-alerte\">Urgence</span></h4><ul><li><span class=\"kw-etio\">vascularite</span> des vasa nervorum jusqu'à preuve du contraire ; <span class=\"kw-alerte\">le retard = séquelles motrices définitives</span></li></ul><h4>Bilan</h4><ul><li><span class=\"kw-imagerie\">ENMG</span> (atteinte pluritronculaire <span class=\"kw-clinique\">axonale asymétrique</span>) + <span class=\"kw-bio\">biopsie neuromusculaire</span> (<span class=\"kw-alerte\">nécrose fibrinoïde</span>) + bilan systémique (<span class=\"kw-bio\">NFS VS CRP</span>, créat/<span class=\"kw-bio\">protéinurie</span>, <span class=\"kw-bio\">sérologies</span> <span class=\"kw-etio\">VHB</span>/VHC/VIH, complément, FR, cryoglobulinémie, <span class=\"kw-bio\">ANCA</span>, FAN)</li></ul><h4>Signes systémiques</h4><ul><li><span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-clinique\">livedo</span>, <span class=\"kw-clinique\">purpura</span></li><li>atteinte rénale / ORL</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">corticoïdes</span> ± <span class=\"kw-ttt\">immunosuppresseurs</span> en <span class=\"kw-alerte\">urgence</span> ; chez le diabétique évident, <span class=\"kw-ttt\">biopsie</span> non nécessaire</li></ul><h4>Renvoi</h4><ul><li>obj-9, obj-10 · Item 193 — Vascularite</li></ul>"},{"id":"t-mn","kind":"terminal","label":"Mononeuropathie — compression / traumatisme","color":"blue","detail":"<h4>Tableau</h4><ul><li>un <span class=\"kw-clinique\">tronc nerveux unique</span>, déficit systématisé au territoire, installation aiguë (<span class=\"kw-etio\">compression</span>, <span class=\"kw-etio\">traumatisme</span>)</li></ul><h4>Examen</h4><ul><li><span class=\"kw-imagerie\">ENMG</span> localise et quantifie ; chercher une cause locale (canal carpien, fibulaire au col de la fibula…)</li></ul><h4>Renvoi</h4><ul><li>obj-2 · Item 95 — Radiculalgie / syndrome canalaire</li></ul>"},{"id":"q-prn","kind":"decision","label":"Polyradiculonévrite (PRN) — aiguë ou chronique ? — Le mode d'installation oriente la PEC","branches":[{"to":"t-gb","label":"Aiguë < 4 sem, ascendante","color":"red"},{"to":"t-pidc","label":"Chronique > 8 sem","color":"amber"}]},{"id":"t-gb","kind":"terminal","label":"URGENCE — Guillain-Barré → LCS + ENMG + surveillance respiratoire","color":"red","detail":"<h4>Reconnaître</h4><ul><li><span class=\"kw-clinique\">déficit ascendant rapide</span> + <span class=\"kw-clinique\">aréflexie diffuse</span> = Guillain-Barré jusqu'à preuve du contraire</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">LCS</span> : dissociation albumino-cytologique ; <span class=\"kw-imagerie\">ENMG</span> démyélinisant</li></ul><h4>Gravité</h4><ul><li><span class=\"kw-alerte\">atteinte respiratoire + déglutition</span> → <span class=\"kw-def\">surveillance</span> continue, <span class=\"kw-alerte\">hospitalisation</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Ig IV</span> ou <span class=\"kw-ttt\">plasmaphérèse</span></li></ul><h4>Renvoi</h4><ul><li>Item 97 — Polyradiculonévrite aiguë</li></ul>"},{"id":"t-pidc","kind":"terminal","label":"PIDC → corticoïdes + Ig IV","color":"amber","detail":"<h4>Tableau</h4><ul><li>forme chronique (&gt; 8 sem), <span class=\"kw-clinique\">évolution</span> par poussées ou progressive</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">hyperprotéinorachie</span> ; <span class=\"kw-imagerie\">ENMG</span> démyélinisant chronique avec blocs</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">corticoïdes + Ig IV</span></li></ul><h4>Renvoi</h4><ul><li>obj-7</li></ul>"},{"id":"t-ganglio","kind":"terminal","label":"Neuronopathie sensitive (ganglionopathie) → bilan paranéoplasique","color":"amber","detail":"<h4>Tableau</h4><ul><li>atteinte des corps cellulaires sensitifs (<span class=\"kw-def\">ganglion rachidien</span>) ; <span class=\"kw-clinique\">aréflexie diffuse</span>, <span class=\"kw-clinique\">ataxie</span> ; <span class=\"kw-imagerie\">ENMG</span> : abolition diffuse des potentiels sensitifs, potentiels moteurs normaux</li></ul><h4>Bilan <span class=\"kw-etio\">paranéoplasique</span></h4><ul><li><span class=\"kw-alerte\">éliminer un cancer du poumon à petites cellules</span> : <span class=\"kw-bio\">AC anti-Hu</span>, <span class=\"kw-imagerie\">TDM thoracique + TEP-TDM</span> ; aussi Gougerot-Sjögren, sels de platine</li></ul><h4>Piège</h4><ul><li>délai neuronopathie → cancer pouvant atteindre <span class=\"kw-chiffre\">1 à 2 ans</span></li></ul><h4>Renvoi</h4><ul><li>obj-3, obj-8 · Item 309 — Tumeurs du poumon</li></ul>"}]},"cards":[{"i":"6569a51004f1","n":96,"o":"96-2","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une neuropathie périphérique (examen clinique, démarche diagnostique)","q":"Quel est le piège diagnostique classique concernant les polyneuropathies axonales longueur-dépendantes, notamment chez le diabétique âgé ?","a":"<p>Une polyneuropathie axonale longueur-dépendante peut être <strong>longtemps paucisymptomatique</strong> chez un diabétique âgé. L'examen des pieds avec un <strong>monofilament 10 g</strong> est obligatoire à chaque consultation pour dépister cette complication.</p>"},{"i":"90f51fafa371","n":96,"o":"96-2","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une neuropathie périphérique (examen clinique, démarche diagnostique)","q":"Quels sont les principaux signes cliniques évoquant un syndrome neurogène périphérique ?","a":"<ul><li><strong>Déficit moteur périphérique</strong>: faiblesse, fatigabilité anormale à l'effort.</li><li><strong>Amyotrophie</strong> (apparaît après quelques semaines d'évolution).</li><li><strong>Crampes, fasciculations</strong>: témoignent de l'atteinte du motoneurone inférieur.</li><li><strong>Troubles sensitifs</strong>: paresthésies, dysesthésies, hypoesthésie.</li><li><strong>Aréflexie ou hyporéflexie</strong>: abolition ou diminution des réflexes ostéo-tendineux (ROT).</li><li><strong>Absence de signe pyramidal</strong>: pas de Babinski, pas de spasticité.</li></ul>"},{"i":"bc449e67f3c4","n":96,"o":"96-2","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une neuropathie périphérique (examen clinique, démarche diagnostique)","q":"Quelle est la première étape de la démarche diagnostique d'une neuropathie périphérique ?","a":"<p>La première étape consiste à <strong>reconnaître le syndrome neurogène périphérique</strong>.</p>"},{"i":"fd3d3f41c3fd","n":96,"o":"96-2","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une neuropathie périphérique (examen clinique, démarche diagnostique)","q":"Face à une suspicion de neuropathie périphérique, quels éléments de l'interrogatoire et de l'examen clinique doivent être systématiquement recherchés ?","a":"<ul><li><strong>Interrogatoire</strong>: Rechercher les antécédents familiaux, la prise de médicaments neurotoxiques, un diabète, une consommation d'alcool, ou une exposition professionnelle.</li><li><strong>Examen clinique</strong>: Explorer la sensibilité <strong>tactile, thermoalgique, proprioceptive</strong> et <strong>vibratoire</strong>; évaluer les <strong>réflexes ostéo-tendineux (ROT)</strong>; réaliser un <strong>testing de la force musculaire</strong>. Pour la composante douloureuse, le <strong>questionnaire DN4</strong> peut être utilisé.</li></ul>"},{"i":"23bc0ef10caf","n":96,"o":"96-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une polyneuropathie, d’une mononeuropathie, d’une mononeuropathie multiple, d’une polyradiculoneuropathie (examen clinique, démarche diagnostique)","q":"Quelles sont les caractéristiques topographiques et cliniques d'une polyneuropathie ?","a":"<p>Une polyneuropathie se caractérise par :</p><ul><li><strong>Topographie</strong> : <strong>longueur-dépendante</strong>, <strong>symétrique</strong>, <strong>distale</strong> (syndrome en « <strong>gants et chaussettes</strong> »).</li><li><strong>Installation</strong> : subaiguë ou chronique.</li><li><strong>Atteinte</strong> : <strong>sensitive supérieure à motrice</strong>, avec des <strong>réflexes ostéotendineux (ROT) abolis distalement</strong>.</li><li><strong>Absence d'atteinte respiratoire ou des nerfs crâniens</strong>.</li></ul>"},{"i":"98474d1e2c66","n":96,"o":"96-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une polyneuropathie, d’une mononeuropathie, d’une mononeuropathie multiple, d’une polyradiculoneuropathie (examen clinique, démarche diagnostique)","q":"Quelles sont les quatre questions clés à se poser devant tout déficit neurologique distal pour orienter le diagnostic topographique d'une neuropathie diffuse ?","a":"<p>Les quatre questions clés sont :</p><ul><li>Le déficit est-il <strong>symétrique ou asymétrique</strong> ?</li><li>Est-il <strong>proximal ou distal</strong> ?</li><li>Atteint-il les <strong>racines ou les troncs nerveux</strong> ?</li><li>L'atteinte est-elle <strong>sensitive, motrice ou les deux</strong> ?</li></ul><p>Ces questions permettent d'orienter vers une polyneuropathie (PNP), une mononeuropathie (MN), une mononeuropathie multiple (MNM) ou une polyradiculonévrite (PRN) avant même la réalisation de l'électromyogramme (ENMG).</p>"},{"i":"d10d4bb75f93","n":96,"o":"96-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une polyneuropathie, d’une mononeuropathie, d’une mononeuropathie multiple, d’une polyradiculoneuropathie (examen clinique, démarche diagnostique)","q":"Quelles sont les caractéristiques cliniques et paracliniques d'une polyradiculonévrite ?","a":"<p>Une polyradiculonévrite se manifeste par :</p><ul><li><strong>Topographie</strong> : atteinte des <strong>racines, des troncs nerveux et des nerfs crâniens</strong>, bilatérale, symétrique, <strong>proximale ET distale</strong>.</li><li><strong>Installation</strong> : aiguë (jours) ou chronique.</li><li><strong>Atteinte</strong> : <strong>sensitive ET motrice</strong>, avec une <strong>aréflexie diffuse</strong>.</li><li><strong>Paraclinique</strong> : une <strong>hyperprotéinorachie</strong> du liquide céphalo-rachidien (LCS) est typique.</li></ul>"},{"i":"fd2c6aea8de5","n":96,"o":"96-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une polyneuropathie, d’une mononeuropathie, d’une mononeuropathie multiple, d’une polyradiculoneuropathie (examen clinique, démarche diagnostique)","q":"Comment distinguer une mononeuropathie d'une mononeuropathie multiple sur le plan clinique ?","a":"<p>Ces deux entités se distinguent comme suit :</p><ul><li><strong>Mononeuropathie</strong> : atteinte d'<strong>un tronc nerveux unique</strong>, focale, avec une installation aiguë (ex: compression, traumatisme) et une atteinte sensitive et motrice systématisée au territoire du nerf.</li><li><strong>Mononeuropathie multiple (multinévrite)</strong> : atteinte de <strong>multiples troncs nerveux</strong>, de façon <strong>asymétrique et asynchrone</strong>. Son installation est aiguë ou subaiguë, et elle constitue une <strong>urgence diagnostique</strong> nécessitant d'évoquer une <strong>vascularite</strong>.</li></ul>"},{"i":"15002799e264","n":96,"o":"96-5","u":"Diagnostic positif","t":"Distinguer cliniquement une neuropathie périphérique et sclérose latérale amyotrophique","q":"Quelle est la différence fondamentale en termes de sensibilité entre une neuropathie périphérique et une sclérose latérale amyotrophique (SLA) ?","a":"<p>Dans le cas d'une <strong>neuropathie périphérique</strong>, on retrouve généralement une <strong>atteinte sensitive</strong> (sauf cas particuliers). En revanche, l'examen sensitif est <strong>normal</strong> dans la <strong>SLA</strong>.</p>"},{"i":"175b68bb94e2","n":96,"o":"96-5","u":"Diagnostic positif","t":"Distinguer cliniquement une neuropathie périphérique et sclérose latérale amyotrophique","q":"Comment différencier une sclérose latérale amyotrophique (SLA) d'un diagnostic différentiel comme la Neuropathie Motrice Multifocale avec Blocs de Conduction (NMMBC) en présence de certains signes cliniques fréquents ?","a":"<p>Devant un déficit moteur distal isolé avec amyotrophie et fasciculations, la présence de <strong>ROT vifs et d'un signe de Babinski positif</strong> oriente fortement vers une <strong>SLA</strong>. La NMMBC peut mimer une SLA avec des ROT parfois vifs malgré l'atrophie, mais <strong>sans signe de Babinski</strong>.</p>"},{"i":"1d1b0a0c2a7a","n":96,"o":"96-5","u":"Diagnostic positif","t":"Distinguer cliniquement une neuropathie périphérique et sclérose latérale amyotrophique","q":"Comment l'examen clinique permet-il de différencier une neuropathie périphérique d'une sclérose latérale amyotrophique (SLA) concernant les motoneurones atteints ?","a":"<p>La <strong>neuropathie périphérique</strong> implique une atteinte du <strong>nerf périphérique</strong> (motoneurone inférieur et fibres sensitives). La <strong>SLA</strong> est caractérisée par une dégénérescence des <strong>motoneurones supérieur ET inférieur</strong>.</p>"},{"i":"3893148d8d0a","n":96,"o":"96-5","u":"Diagnostic positif","t":"Distinguer cliniquement une neuropathie périphérique et sclérose latérale amyotrophique","q":"Quelles sont les spécificités des réflexes ostéo-tendineux (ROT) et des signes pyramidaux pour distinguer une neuropathie périphérique d'une sclérose latérale amyotrophique (SLA) ?","a":"<p>Pour la <strong>neuropathie périphérique</strong>, les ROT sont <strong>abolis ou diminués</strong> et les signes pyramidaux sont <strong>absents</strong>. Pour la <strong>SLA</strong>, les ROT sont <strong>vifs et polycinétiques</strong>, souvent associés à un <strong>signe de Babinski</strong>, une <strong>hyperréflexie</strong> et une <strong>spasticité</strong> (signes pyramidaux).</p>"},{"i":"9164cd5bc8a8","n":96,"o":"96-5","u":"Diagnostic positif","t":"Distinguer cliniquement une neuropathie périphérique et sclérose latérale amyotrophique","q":"Que révèle l'électromyogramme (ENMG) dans les cas de neuropathie périphérique et de sclérose latérale amyotrophique (SLA) ?","a":"<p>L'ENMG d'une <strong>neuropathie périphérique</strong> montre une <strong>atteinte axonale ou démyélinisante du nerf</strong>. Dans la <strong>SLA</strong>, l'ENMG révèle une <strong>atteinte neurogène pure</strong> de la corne antérieure, <strong>sans atteinte sensitive</strong>.</p>"}]};